                |       include {
                            if (!push_include($1, false)) {
                                parser_leak_remove(LEAK_PTR, $1);
                                free($1);
                                YYERROR;
                            }
                            parser_leak_remove(LEAK_PTR, $1);
                            free($1);
                        }
                |       includedir {
                            if (!push_include($1, true)) {
                                parser_leak_remove(LEAK_PTR, $1);
                                free($1);
                                YYERROR;
                            }
                            parser_leak_remove(LEAK_PTR, $1);
                            free($1);
                        }
